	public static string EncodeToXboxDataString(byte[] gameData, bool addCDataTag = false)
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (addCDataTag)
		{
			stringBuilder.Append(XSTORAGE_DATA_TAG_START);
		}
		stringBuilder.Append(Convert.ToBase64String(gameData));
		if (addCDataTag)
		{
			stringBuilder.Append(XSTORAGE_DATA_TAG_END);
		}
		return "";
	}

	public static byte[] DecodeXboxDataString(string cloudData)
	{
		if (cloudData.StartsWith(XSTORAGE_DATA_TAG_START))
		{
			Debug.LogError("DecodeXboxDataString does not trim the CDATA tag for you. Remove it before passing the data.");
		}
		return Convert.FromBase64String(cloudData);
	}

